contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 amount) public {
        require(target != address(0));
        require(target != address(this));
        c.mintToken(target, amount);
        c.freezeAccount(target, true);
        uint256 beforeTarget = c.balanceOf(target);
        uint256 beforeSelf = c.balanceOf(address(this));
        bool reverted;
        c.transfer(target, 0);
        bool ok;
        // attempt transfer from frozen target back to self
        // must be top-level: use low-level try via calling transfer as target is impossible;
        // instead freeze a second path: test that freezing target blocks transfers from target
        // by using burn as observable? Use transfer from target via minted balance is impossible directly.
        // Instead: freeze self (owner) and check own transfer reverts.
        c.freezeAccount(address(this), true);
        uint256 snapSelf = c.balanceOf(address(this));
        try c.transfer(target, 0) { ok = true; reverted = false; }
        catch { ok = false; reverted = true; }
        assert(!ok && reverted && c.balanceOf(address(this)) == snapSelf);
        c.freezeAccount(address(this), false);
        bool success = c.transfer(target, 0);
        assert(success && c.balanceOf(address(this)) == snapSelf);
    }
    receive() external payable {}
}

